///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리

        txb_chk_date.hide();
        txb_seq.hide();
        txb_act_tp_cd.hide();
        txb_approv_stat_cd.hide();
        txb_emp_no.hide();
        txb_chg_bfaf_tp_cd.hide();
        txb_before_seq.hide();
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        scwin.getParentValue();
        await scwin.getProcsTeamCheck();
        if (scwin.regMode === 'REG') {
            await scwin.setInfoHeader();
            scwin.getParentValue();
            await scwin.setlistHeader();
            await scwin.regBeforeList();
            await scwin.regAfterList();
            dts_set_design.setBroadcast(false);
            for (let i = 1; i <= dts_list_af_design.getRowCount(); i++) {
                dts_set_design.insertRow();
                dts_set_design.setCellData(i, "CPOC_DESIGN_RSN_CD", dts_list_af_design.getCellData(i, "CPOC_DESIGN_RSN_CD"));
                dts_set_design.setCellData(i, "CPOC_DESIGN_RSN_NM", dts_list_af_design.getCellData(i, "CPOC_DESIGN_RSN_NM"));
            }
            dts_set_design.setBroadcast(true, true);
        } else if (scwin.regMode === 'MOD') {
            await scwin.setlistHeader();
            await scwin.readInfo(); // 기본정보 불러오기
            await scwin.modBeforeList();
            await scwin.modAfterList();
            txb_chk_date.setValue(edt_strt_dd.getValue());
        } else if (scwin.regMode === 'APP') {
            await scwin.setlistHeader();
            await scwin.readInfo(); // 기본정보 불러오기
            await scwin.modBeforeList();
            await scwin.modAfterList();
        } else {
            await scwin.setlistHeader();
            await scwin.readInfo(); // 기본정보 불러오기
            await scwin.modBeforeList();
            await scwin.modAfterList();
        }
        txb_emp_no.setValue(scwin.gEmpNo);
        txb_chg_bfaf_tp_cd.setValue('2'); // 변경후
        txb_before_seq.setValue(dts_list_bf_design.getCellData(0, "CPOC_SEQ"));
        $c.stf.doLogSave('ULDSTF37701.xml', SCREN_PROCS_TP_CD_01);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37702.onpageload" });
    }
};

