/**
 * @method
 * @name procs
 * @description 등록 및 수정 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procs = async function() {
    const vStrt_dd = edt_strt_dd.getValue();
    if (vStrt_dd === '') {
        await $c.win.alert("지정일을 선택하세요");
        edt_strt_dd.focus();
        return;
    }
    if (vStrt_dd <= $c.ut.cGetToday("yyyymmdd")) {
        await $c.win.alert("지정일을 오늘 날짜 이후로 지정하세요");
        edt_strt_dd.focus();
        return;
    }

    // 매매일 체크
    if (!$c.lc.fn_TrHoldyYn(dts_checkDD, vStrt_dd)) {
        edt_strt_dd.focus();
        return;
    }

    // 지정일 체크
    if (await scwin.checkEnforceDD(scwin.gIsurCd, vStrt_dd) === false) {
        edt_strt_dd.focus();
        return;
    }
    if (dts_list_af_design.getRowCount() < 1) {
        await $c.win.alert("지정사유를 선택하세요.");
        return;
    }

    // 지정사유 체크 변경 전 지정사유와 변경 후 지정사유가 같으면 안됨
    // if(fn_checkBfAfDesign() == false){
    //    return;
    // }

    let tmpStr;
    let vMethod;
    let vKeyValeue;
    if (scwin.regMode === 'REG') {
        tmpStr = "저장 하시겠습니까?";
        vMethod = "insertChgConfrmProcsObjCorp";
        vKeyValeue = "JSP(I:pInput1=dts_info_design,I:pInput2=dts_set_design,I:pInput3=dts_list_bf_design)";
        // vKeyValeue = "JSP(I:pInput1=dts_info_design,I:pInput2=dts_list_af_design,I:pInput3=dts_list_bf_design)";

    } else if (scwin.regMode === 'MOD') {
        tmpStr = "수정 하시겠습니까?";
        vMethod = "updateConfrmProcsObjCorp";
        vKeyValeue = "JSP(I:pInput1=dts_info_design,I:pInput2=dts_list_af_design)";
    }
    let vAnswer = confirm(tmpStr);
    if (vAnswer === true) {
        trs_insert.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_insert",
            action : "/ConfrmProcs.do",
            ref : "",
            target : "trs_insert=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name approvStatProcs
 * @description 승인상태 처리
 * @param {*} gbn gbn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.approvStatProcs = async function(gbn) {
    let tmpStr;
    let vMethod;
    vMethod = "updateApprovStatCd";
    if (gbn === '20') {
        tmpStr = "검토 하시겠습니까?";
    } else if (gbn === '30') {
        tmpStr = "승인 하시겠습니까?";
    } else if (gbn === '40') {
        tmpStr = "유보 하시겠습니까?";
    }

    // 유보일 경우 접수 상태로 변경한다.
    if (gbn === '40') {
        txb_approv_stat_cd.setValue("10");
    } else {
        txb_approv_stat_cd.setValue(gbn);
    }
    let vAnswer = confirm(tmpStr);
    if (vAnswer === true) {
        trs_approvUpdate.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_approvUpdate",
            action : "/ConfrmProcs.do",
            ref : "dts_info_design",
            target : "trs_approvUpdate=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
