/**
 * @method
 * @name checkEnforceDD
 * @description 지정일 체크
 * @param {String} pIsurCd pIsurCd
 * @param {*} pStrt_dd pStrt_dd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkEnforceDD = async function(pIsurCd, pStrt_dd) {
    let vENFORCE_DD;
    const sbmOptions = {
        id : "sbm_dts_checkDD",
        action : "/ConfrmProcs.do",
        ref : "",
        target : "dts_checkDD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    vENFORCE_DD = dts_checkDD.getCellData(1, "CPOC_ENFORCE_DD");

    // 지정가능한 날짜가 있으면
    if (vENFORCE_DD === undefined) {
        return true;
        // 수정 화면에서 저장된 날짜와 같으면
    } else if (txb_chk_date.getValue() === pStrt_dd) {
        return true;
        // 입력한 일자가 같은 날짜에 있으면
    } else if (vENFORCE_DD === pStrt_dd) {
        await $c.win.alert("입력한 일자에 예정된 확인절차 대상법인 처리 업무가 있습니다.");
        return false;
        // 입력한 일자가 이후 날짜에 있으면
    } else {
        await $c.win.alert("입력한 일자 이후에 예정된 확인절차 대상법인 처리 업무가 있습니다.");
        return false;
    }
    return true;
};

