// 팀장  : 09,  부서장: 40,  팀원: 03

/**
 * @method
 * @name getParentValue
 * @description 부모창에서 필요변수 저장
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    scwin.regMode = frame.opener.scwin.regMode;
    if (scwin.regMode === "REG") {
        scwin.gSeq = "0";
        scwin.gApprovStatCd = "10";
        txb_approv_stat_cd.setValue(scwin.gApprovStatCd);
    } else {
        scwin.gSeq = frame.opener.scwin.gSeq;
    }
    scwin.gIsurCd = frame.opener.scwin.gIsurCd;
    gComAbbrv = frame.opener.gComAbbrv;
    scwin.gActTpCd = frame.opener.scwin.gActTpCd;
    txb_seq.setValue(scwin.gSeq);
    txb_isur_cd.setValue(scwin.gIsurCd);
    txb_com_abbrv.setValue(gComAbbrv);
    txb_act_tp_cd.setValue(scwin.gActTpCd);
    txb_emp_no.setValue(scwin.gEmpNo);
};

/**
 * @method
 * @name showProcButton
 * @description 버튼 권한 체크 panel_proc_1 : 검토, 삭제, 저장 panel_proc_2 : 승인, 유보 panel_proc_3 : 달력,  사유추가, 사유삭제
 * @param {String} pDepCd pDepCd
 * @param {*} pEmpNo pEmpNo
 * @returns {void}
 * @hidden N
 */
scwin.showProcButton = function(pDepCd, pEmpNo) {
    // 팀장, 당번팀장, 당번인 경우
    if (scwin.gJobTitle === '09' || scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y') {
        // 검토, 삭제, 수정 처리
        if (scwin.regMode === 'MOD') {
            btn_Save.setBackgroundImage("../img/btn_modify.gif");
            panel_proc_2.hide();
            // 승인, 유보 처리

        } else if (scwin.regMode === 'APP') {
            panel_proc_1.hide();
            panel_proc_3.hide();
            edt_strt_dd.setReadOnly(true);
            txa_remk.setReadOnly(true);
            // 상세 화면 버튼은 모두 안보이게 처리

        } else if (scwin.regMode === 'VIEW') {
            panel_proc_1.hide();
            panel_proc_2.hide();
            panel_proc_3.hide();
            edt_strt_dd.setReadOnly(true);
            txa_remk.setReadOnly(true);
        } else {
            btn_Review.hide();
            btn_Del.hide();
            panel_proc_2.hide();
        }
        // 팀원이고 같은 팀인 경우

    } else if (scwin.gJobTitle === '03' && scwin.gDepCd === pDepCd) {
        // 검토, 삭제, 수정 처리
        if (scwin.regMode === 'MOD') {
            btn_Save.setBackgroundImage("../img/btn_modify.gif");
            panel_proc_2.hide();
            // 승인, 유보 처리

        } else if (scwin.regMode === 'APP') {
            panel_proc_1.hide();
            panel_proc_2.hide();
            panel_proc_3.hide();
            edt_strt_dd.setReadOnly(true);
            txa_remk.setReadOnly(true);
            // 상세 화면 버튼은 모두 안보이게 처리

        } else if (scwin.regMode === 'VIEW') {
            panel_proc_1.hide();
            panel_proc_2.hide();
            panel_proc_3.hide();
            edt_strt_dd.setReadOnly(true);
            txa_remk.setReadOnly(true);
        } else {
            btn_Review.hide();
            btn_Del.hide();
            panel_proc_2.hide();
        }
    } else {
        panel_proc_1.hide();
        panel_proc_2.hide();
        panel_proc_3.hide();
        edt_strt_dd.setReadOnly(true);
        txa_remk.setReadOnly(true);
    }
};

/**
 * @method
 * @name checkBfAfDesign
 * @description 지정사유 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkBfAfDesign = async function() {
    let bf_result = "";
    let af_result = "";

    // 변경 전 지정사유
    for (let i = 1; i <= dts_list_bf_design.getRowCount(); i++) {
        bf_result += dts_list_bf_design.getCellData(i, "CPOC_DESIGN_RSN_CD") + ',';
    }

    // 변경 후 지정사유
    for (let k = 1; k <= dts_list_af_design.getRowCount(); k++) {
        af_result += dts_list_af_design.getCellData(k, "CPOC_DESIGN_RSN_CD") + ',';
    }
    if (bf_result.substring(0, bf_result.length - 1) === af_result.substring(0, af_result.length - 1)) {
        await $c.win.alert("변경 전 지정사유와 변경 후 지정사유가 같습니다.");
        return false;
    }
};

