/**
 * @method
 * @name setParRsnCd
 * @description 선택된 사유코드 중복체크
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParRsnCd = function(arrPar) {
    // 선택된 사유코드 중복체크
    if (!$c.lc.fn_isNewValueForDataSet(dts_list_af_design, "CPOC_DESIGN_RSN_CD", arrPar[0])) return;
    dts_list_af_design.insertRow();
    dts_list_af_design.setCellData(dts_list_af_design.getRowPosition(), "CPOC_DESIGN_RSN_CD", arrPar[0]);
    dts_list_af_design.setCellData(dts_list_af_design.getRowPosition(), "CPOC_DESIGN_RSN_NM", arrPar[1]);
    dts_list_af_design.sort("CPOC_DESIGN_RSN_CD", 0);
    // dts_list_af_design.sort(); // W-Craft 주석처리

    // if( !fn_isNewValueForDataSet( dts_set_design ,"CPOC_DESIGN_RSN_CD" , arrPar[0]) ) return ;

    dts_set_design.insertRow();
    dts_set_design.setCellData(dts_set_design.getRowPosition(), "CPOC_DESIGN_RSN_CD", arrPar[0]);
    dts_set_design.setCellData(dts_set_design.getRowPosition(), "CPOC_DESIGN_RSN_NM", arrPar[1]);
    dts_set_design.sort("CPOC_DESIGN_RSN_CD", 0);
    // dts_set_design.sort(); // W-Craft 주석처리

};

